import{_ as t,o,c as s,ae as n}from"./chunks/framework.DPZ3sAUK.js";const g=JSON.parse('{"title":"Context, State, and Hooks","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/context-and-state.md","filePath":"concepts/context-and-state.md"}'),a={name:"concepts/context-and-state.md"};function i(c,e,r,l,d,u){return o(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="context-state-and-hooks" tabindex="-1">Context, State, and Hooks <a class="header-anchor" href="#context-state-and-hooks" aria-label="Permalink to &quot;Context, State, and Hooks&quot;">​</a></h1><p>Managing state effectively is critical for dynamic logic engines. <code>neuron-js</code> uses the <strong>ExecutionContext</strong> to achieve this.</p><h2 id="executioncontext" tabindex="-1">ExecutionContext <a class="header-anchor" href="#executioncontext" aria-label="Permalink to &quot;ExecutionContext&quot;">​</a></h2><p>The <code>ExecutionContext</code> is a shared object that travels with the execution flow.</p><ul><li><strong>Storage</strong>: It typically holds a <code>state</code> object (the primary data being processed) and a <code>messages</code> list (for logging/audit trails).</li><li><strong>Mutations</strong>: Actions can return a modified version of the context. This allows an action to &quot;enrich&quot; the state for subsequent elements.</li><li><strong>Access</strong>: Both Conditions and Actions have full access to the context, allowing them to make decisions or perform tasks based on the current state of the system.</li></ul><h2 id="executionresult" tabindex="-1">ExecutionResult <a class="header-anchor" href="#executionresult" aria-label="Permalink to &quot;ExecutionResult&quot;">​</a></h2><p>When a script finishes (or fails), the <code>Synapse</code> returns an <code>ExecutionResult</code>. This object contains:</p><ul><li><strong>Success Flag</strong>: Whether the execution completed without runtime errors.</li><li><strong>Final Context</strong>: The state after all successful actions have run.</li><li><strong>Metadata</strong>: Information such as the number of rules executed and any error/info messages collected during the run.</li></ul><h2 id="lifecycle-hooks" tabindex="-1">Lifecycle Hooks <a class="header-anchor" href="#lifecycle-hooks" aria-label="Permalink to &quot;Lifecycle Hooks&quot;">​</a></h2><p>Hooks allow external systems to monitor and react to the execution engine&#39;s internal states.</p><p>Common Hook Events:</p><ul><li><code>ON_SCRIPT_START</code> / <code>ON_SCRIPT_END</code></li><li><code>ON_RULE_START</code> / <code>ON_RULE_END</code></li><li><code>ON_CONDITION_START</code> / <code>ON_ACTION_START</code></li><li><code>ON_ERROR</code> (Generic or specific to elements)</li></ul><h3 id="use-cases-for-hooks" tabindex="-1">Use Cases for Hooks: <a class="header-anchor" href="#use-cases-for-hooks" aria-label="Permalink to &quot;Use Cases for Hooks:&quot;">​</a></h3><ul><li><strong>Logging</strong>: Send execution logs to a centralized system (e.g., ELK stack).</li><li><strong>Telemetry</strong>: Track how many times certain rules are firing.</li><li><strong>Debugging</strong>: Inspect the context at specific breakpoints in the execution.</li></ul>',14)])])}const x=t(a,[["render",i]]);export{g as __pageData,x as default};
